const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometry for Monte Pisano, Italy
  const montePisano = ee.Geometry.Point([10.56, 43.73]);
  const region = montePisano.buffer(15000); // 15km buffer for smoke analysis

  // 2. Define date range for February 25, 2019
  const targetDate = '2019-02-25';
  const startDate = '2019-02-24';
  const endDate = '2019-02-26';

  // 3. Load Landsat 8 Collection 2 Level 2
  let collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(montePisano)
    .filterDate(startDate, endDate);

  const imageCount = collection.size().getInfo();
  console.log(`Landsat 8 images found: ${imageCount}`);

  if (imageCount === 0) {
    console.log("No Landsat 8 images found for February 25, 2019.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 4. Get the image
  const image = collection.first();
  const imageDate = ee.Date(image.get('system:time_start')).format('YYYY-MM-dd HH:mm').getInfo();
  console.log(`Image date: ${imageDate}`);

  // 5. Analyze smoke plume direction using aerosol band and thermal data
  // Use SR_B1 (Coastal Aerosol) for smoke detection
  // Compare pixel intensities in different directions from fire center

  // Define directional regions from the fire center
  const fireCenter = ee.Geometry.Point([10.56, 43.73]);
  const eastRegion = ee.Geometry.Rectangle([10.58, 43.71, 10.68, 43.75]); // East of fire
  const westRegion = ee.Geometry.Rectangle([10.46, 43.71, 10.54, 43.75]); // West of fire
  const northRegion = ee.Geometry.Rectangle([10.54, 43.75, 10.58, 43.80]); // North of fire
  const southRegion = ee.Geometry.Rectangle([10.54, 43.68, 10.58, 43.71]); // South of fire

  // Use aerosol band (SR_B1) - higher values indicate smoke/aerosols
  const aerosolBand = image.select('SR_B1');

  // Calculate mean aerosol values in each direction
  const eastMean = aerosolBand.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: eastRegion,
    scale: 1000,
    maxPixels: 1e9
  }).get('SR_B1').getInfo();

  const westMean = aerosolBand.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: westRegion,
    scale: 1000,
    maxPixels: 1e9
  }).get('SR_B1').getInfo();

  const northMean = aerosolBand.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: northRegion,
    scale: 1000,
    maxPixels: 1e9
  }).get('SR_B1').getInfo();

  const southMean = aerosolBand.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: southRegion,
    scale: 1000,
    maxPixels: 1e9
  }).get('SR_B1').getInfo();

  console.log(`Aerosol levels - East: ${eastMean}, West: ${westMean}, North: ${northMean}, South: ${southMean}`);

  if (eastMean === null || westMean === null || northMean === null || southMean === null) {
    console.log("Cannot calculate aerosol values.");
    console.log("<answer>C3</answer>");
    return;
  }

  // 6. Determine smoke plume direction
  // If east has significantly higher aerosol than west, smoke is moving east
  const maxDirection = Math.max(eastMean, westMean, northMean, southMean);

  console.log(`Maximum aerosol in: ${maxDirection === eastMean ? 'East' : maxDirection === westMean ? 'West' : maxDirection === northMean ? 'North' : 'South'}`);

  // Smoke plume moving east if eastern aerosol is highest or significantly elevated
  if (eastMean === maxDirection && eastMean > westMean * 1.1) {
    console.log("Smoke plume shows eastward movement pattern.");
    console.log("<answer>A</answer>");
  } else {
    console.log("Smoke plume does not show clear eastward movement.");
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
